{
  "actionBar.toggledBackground": {
    "for": "Background color for toggled action items in action bar."
  },
  "activeSessionView.background": {
    "for": "Background color of an active session view in the agent sessions window."
  },
  "activeSessionView.foreground": {
    "for": "Foreground color of an active session view in the agent sessions window."
  },
  "activityBar.activeBackground": {
    "for": "Active activity bar item backgrounds."
  },
  "activityBar.activeBorder": {
    "for": "Activity bar border color for the active item. The activity bar is showing on the far left or right and allows to switch between views of the side bar."
  },
  "activityBar.activeFocusBorder": {
    "for": "Activity bar focus border color for the active item. The activity bar is showing on the far left or right and allows to switch between views of the side bar."
  },
  "activityBar.background": {
    "for": "Activity bar backgrounds."
  },
  "activityBar.border": {
    "for": "Activity bar border color separating to the side bar. The activity bar is showing on the far left or right and allows to switch between views of the side bar."
  },
  "activityBar.dropBorder": {
